<section class="container pb-5"><div class="row g-4"><div class="col-lg-4"><div class="surface surface-pad"><div class="avatar-mini mb-3" style="width:58px;height:58px;font-size:1.4rem"><?= e(strtoupper(substr($profile['nama'],0,1))) ?></div><h2 style="font:500 1.7rem Georgia,serif"><?= e($profile['nama']) ?></h2><p class="muted mb-2"><?= e($profile['email']) ?></p><span class="badge text-bg-dark"><?= e(ucfirst($profile['peran'])) ?></span><hr><p class="form-note mb-0">Email, username, dan peran tidak dapat diubah dari formulir profil.</p></div></div><div class="col-lg-8"><div class="surface surface-pad"><h2 class="h5 mb-4">Informasi pribadi</h2><form method="post" action="<?= e(url('profile')) ?>"><?= csrf_field() ?><div class="mb-3"><label class="form-label" for="nama">Nama lengkap</label><input class="form-control" name="nama" id="nama" required maxlength="100" value="<?= e($profile['nama']) ?>"></div><div class="mb-4"><label class="form-label" for="no_telepon">Nomor telepon / WhatsApp</label><input class="form-control" name="no_telepon" id="no_telepon" maxlength="20" value="<?= e($profile['no_telepon']) ?>"></div><div class="divider-label">Ganti kata sandi (opsional)</div><div class="mb-3"><label class="form-label" for="password_lama">Kata sandi lama</label><input class="form-control" type="password" id="password_lama" name="password_lama" autocomplete="current-password"></div><div class="row g-3"><div class="col-md-6"><label class="form-label" for="password_baru">Kata sandi baru</label><input class="form-control" type="password" id="password_baru" name="password_baru" minlength="8" autocomplete="new-password"><div class="form-note">Minimal 8 karakter, kosongkan bila tidak diganti.</div></div><div class="col-md-6"><label class="form-label" for="konfirmasi_password">Konfirmasi kata sandi baru</label><input class="form-control" type="password" id="konfirmasi_password" name="konfirmasi_password" minlength="8" autocomplete="new-password"></div></div><button class="btn btn-copper mt-4" type="submit">Simpan Perubahan</button></form></div></div></div></section>
